/* Ancient Octopus 81 by mrtqzbek11 — https://uiverse.io/mrtqzbek11/ancient-octopus-81 */
button {
  width: 136px;
  height: 46px;
  background-color: #19fb9b;
  border: 1px solid black;
  border-radius: 6px;
  cursor: pointer;
  font-size: 17px;
  transition: .4s;
}

button:hover {
  box-shadow: 5px 6px 0px rgb(0, 0, 0);
}
